using System.Security.Cryptography;
using DotReticulum.Core;
using static DotReticulum.Transport.Tests.Parity4LinkMtuTests;

namespace DotReticulum.Transport.Tests;

// Resource.py:653-670,765-774 and Transport.py:2576-2582,3053-3123 at
// a29bfb51c468945c96a1ee22cae0114e993e2391. Packet bytes independently
// generated by executing Resource.prove and Transport.cache_request.
[Trait("Category", "Unit")]
public class Parity4ReceiptCacheTests
{
    [Fact]
    public async Task ForcedProofCacheAndPlaintextQueryMatchExecutedReference()
    {
        await using var node = await Harness.Create();
        var link = FixedInitiator(node);
        var reference = Vectors.GetProperty("resource");
        var proof = Packet.Parse(Hex(reference, "proofRaw"));
        Assert.True(reference.GetProperty("forced").GetBoolean());
        Assert.Equal(Hex(reference, "proofPacketHash"), proof.CalculateHash());
        Assert.Equal(Hex(reference, "hash"), proof.Payload[..32].ToArray());
        Assert.Equal(Resource.ComputeExpectedProof(Hex(reference, "data"), Hex(reference, "hash")), proof.Payload[32..].ToArray());
        link.RequestResourceProof(Hex(reference, "hash"), proof.Payload[32..].ToArray());
        await LinkTests.Until(() => node.Interface.Sent.Any(packet => packet.Context == LinkContext.CacheRequest));
        Assert.Equal(Hex(reference, "queryRaw"), node.Interface.Sent.First(packet => packet.Context == LinkContext.CacheRequest).ToArray());
        node.Router.CacheResourceProof(proof);
        Assert.Equal(1, node.Router.CachedResourceProofCount);
        var query = Packet.Parse(Hex(reference, "queryRaw"));
        Assert.True(await node.Router.HandleResourceCacheRequestAsync(Received(query, node.Interface), CancellationToken.None));
        Assert.Equal(proof.ToArray(), node.Interface.Sent.Last(packet => packet.Context == LinkContext.ResourcePrf).ToArray());
    }

    [Fact]
    public async Task CacheRejectsMalformedQueriesCrossLinkReplayCorruptionAndGenericPackets()
    {
        await using var node = await Harness.Create();
        var reference = Vectors.GetProperty("resource");
        var proof = Packet.Parse(Hex(reference, "proofRaw"));
        node.Router.CacheResourceProof(proof);
        foreach (var length in new[] { 1, 16, 31, 33, 64 })
        {
            var malformed = Packet.Create(PacketType.Data, DestinationType.Link, proof.DestinationHash, new byte[length], LinkContext.CacheRequest);
            Assert.False(await node.Router.HandleResourceCacheRequestAsync(Received(malformed, node.Interface), CancellationToken.None));
        }
        var wrongLink = Packet.Create(PacketType.Data, DestinationType.Link, new byte[16], proof.CalculateHash(), LinkContext.CacheRequest);
        Assert.False(await node.Router.HandleResourceCacheRequestAsync(Received(wrongLink, node.Interface), CancellationToken.None));
        var missing = Packet.Create(PacketType.Data, DestinationType.Link, proof.DestinationHash, new byte[32], LinkContext.CacheRequest);
        Assert.False(await node.Router.HandleResourceCacheRequestAsync(Received(missing, node.Interface), CancellationToken.None));
        Assert.Throws<ArgumentException>(() => node.Router.CacheResourceProof(Packet.Create(PacketType.Proof, DestinationType.Link,
            proof.DestinationHash, new byte[63], LinkContext.ResourcePrf)));
        Assert.Throws<ArgumentException>(() => node.Router.CacheResourceProof(Packet.Create(PacketType.Data, DestinationType.Link,
            proof.DestinationHash, new byte[64], LinkContext.None)));

        await using var restored = await Harness.Create();
        restored.Router.RestoreProofCache([
            new TransportPacketState(new byte[32], proof.ToArray(), false),
            new TransportPacketState(proof.CalculateHash(), [1, 2, 3], false),
            new TransportPacketState(proof.CalculateHash(), proof.ToArray(), true)]);
        Assert.Equal(0, restored.Router.CachedResourceProofCount);
        restored.Router.RestoreProofCache(node.Router.CaptureProofCache());
        Assert.Equal(1, restored.Router.CachedResourceProofCount);
        var query = Packet.Parse(Hex(reference, "queryRaw"));
        using var cancellation = new CancellationTokenSource();
        cancellation.Cancel();
        await Assert.ThrowsAnyAsync<OperationCanceledException>(async () =>
            await restored.Router.HandleResourceCacheRequestAsync(Received(query, restored.Interface), cancellation.Token));
        Assert.Empty(restored.Interface.Sent);
        Assert.True(await restored.Router.HandleResourceCacheRequestAsync(Received(query, restored.Interface), CancellationToken.None));
        Assert.Equal(proof.ToArray(), restored.Interface.Sent.Single().ToArray());
    }

    [Fact]
    public async Task ProofCacheIsBoundedAndExpiresAfterReference24HourRetention()
    {
        var clock = new Clock();
        await using var node = await Harness.Create(clock: clock);
        var linkId = Hex(MtuVector(500), "linkId");
        for (var i = 0; i < 1030; i++)
        {
            var data = new byte[64];
            BitConverter.GetBytes(i).CopyTo(data, 0);
            node.Router.CacheResourceProof(Packet.Create(PacketType.Proof, DestinationType.Link, linkId, data, LinkContext.ResourcePrf));
        }
        Assert.Equal(1024, node.Router.CachedResourceProofCount);
        clock.Advance(24 * 60 * 60);
        Assert.Equal(1024, node.Router.CachedResourceProofCount);
        clock.Advance(0.001);
        Assert.Equal(0, node.Router.CachedResourceProofCount);
    }

    [Fact]
    public async Task RestoredCacheTimestampsUseUnixSecondsAndNeverExtendRetention()
    {
        var clock = new Clock();
        await using var node = await Harness.Create(clock: clock);
        var proof = Packet.Parse(Hex(Vectors.GetProperty("resource"), "proofRaw"));
        var now = node.Router.Links.UnixNow;
        foreach (var timestamp in new[] { double.NaN, double.PositiveInfinity, double.NegativeInfinity, -1, now + 1, now - 86401 })
        {
            node.Router.RestoreProofCache([new TransportPacketState(proof.CalculateHash(), proof.ToArray(), false, timestamp)]);
            Assert.Equal(0, node.Router.CachedResourceProofCount);
        }
        node.Router.CacheResourceProof(proof, now - 86399);
        Assert.Equal(1, node.Router.CachedResourceProofCount);
        clock.Advance(2);
        Assert.Equal(0, node.Router.CachedResourceProofCount);
    }

    [Fact]
    public async Task CaptureAndRestorePreserveFractionalUnixTimestampAndOriginalExpiryAcrossRestart()
    {
        var clock = new Clock();
        clock.Advance(0.125);
        await using var original = await Harness.Create(clock: clock);
        var proof = Packet.Parse(Hex(Vectors.GetProperty("resource"), "proofRaw"));
        original.Router.CacheResourceProof(proof);
        var captured = Assert.Single(original.Router.CaptureProofCache());
        Assert.Equal(original.Router.Links.UnixNow, captured.CachedAt);
        Assert.Equal(proof.ToArray(), captured.Raw);
        Assert.Equal(proof.CalculateHash(), captured.PacketHash);
        Assert.False(captured.Announce);

        var restartClock = new Clock();
        restartClock.Advance(86399.125);
        await using var restarted = await Harness.Create(clock: restartClock);
        restarted.Router.RestoreProofCache([captured]);
        Assert.Equal(captured.CachedAt, Assert.Single(restarted.Router.CaptureProofCache()).CachedAt);
        restartClock.Advance(1);
        Assert.Equal(1, restarted.Router.CachedResourceProofCount);
        restartClock.Advance(0.001);
        Assert.Equal(0, restarted.Router.CachedResourceProofCount);
    }

    [Fact]
    public async Task LegacyNullTimestampIsAssignedOnceAndNotRefreshedByTheNextRestart()
    {
        var clock = new Clock();
        clock.Advance(100.375);
        await using var first = await Harness.Create(clock: clock);
        var proof = Packet.Parse(Hex(Vectors.GetProperty("resource"), "proofRaw"));
        var legacy = new TransportPacketState(proof.CalculateHash(), proof.ToArray(), false);
        Assert.Null(legacy.CachedAt);
        first.Router.RestoreProofCache([legacy]);
        var persisted = Assert.Single(first.Router.CaptureProofCache());
        Assert.NotNull(persisted.CachedAt);
        Assert.Equal(first.Router.Links.UnixNow, persisted.CachedAt);

        var restartClock = new Clock();
        restartClock.Advance(100.375 + 86400);
        await using var second = await Harness.Create(clock: restartClock);
        second.Router.RestoreProofCache([persisted]);
        Assert.Equal(persisted.CachedAt, Assert.Single(second.Router.CaptureProofCache()).CachedAt);
        restartClock.Advance(0.001);
        Assert.Equal(0, second.Router.CachedResourceProofCount);
        second.Router.RestoreProofCache([persisted]);
        Assert.Equal(0, second.Router.CachedResourceProofCount);
    }

    [Theory]
    [InlineData(false, false)]
    [InlineData(true, false)]
    [InlineData(false, true)]
    public async Task LostResourceProofRecoversViaNetworkQueryOrLocalForcedCache(bool localCache, bool cancel)
    {
        var left = new Probe();
        var right = new Probe { Peer = left };
        left.Peer = right;
        await using var sender = await Harness.Create(left, run: true);
        await using var receiver = await Harness.Create(right, run: true);
        using var identity = Identity.Generate();
        var destination = new LocalDestination(identity, Destination.Create(DestinationType.Single, "parity4", ["cache"], identity)) { AcceptLinks = true };
        var accepted = new TaskCompletionSource<Link>(TaskCreationOptions.RunContinuationsAsynchronously);
        destination.LinkEstablished = link => { link.ResourceStrategy = ResourceStrategy.AcceptAll; accepted.TrySetResult(link); };
        receiver.Router.RegisterLocalDestination(destination);
        await receiver.Router.AnnounceAsync(destination);
        await LinkTests.Until(() => sender.Router.HasPath(destination.Destination.Hash));
        var active = new TaskCompletionSource<Link>(TaskCreationOptions.RunContinuationsAsynchronously);
        var initiator = sender.Router.Links.Connect(identity, destination.Destination.Hash, link => active.TrySetResult(link));
        await active.Task.WaitAsync(TimeSpan.FromSeconds(5));
        var responder = await accepted.Task.WaitAsync(TimeSpan.FromSeconds(5));
        var proofs = 0;
        right.Drop = packet => packet.Context == LinkContext.ResourcePrf && Interlocked.Increment(ref proofs) == 1;
        var received = new TaskCompletionSource<Resource>(TaskCreationOptions.RunContinuationsAsynchronously);
        responder.ResourceReceived = resource => received.TrySetResult(resource);
        var complete = new TaskCompletionSource<Resource>(TaskCreationOptions.RunContinuationsAsynchronously);
        var payload = RandomNumberGenerator.GetBytes(32768);
        var outgoing = initiator.SendResource(payload, autoCompress: false, concluded: resource => complete.TrySetResult(resource));
        var incoming = await received.Task.WaitAsync(TimeSpan.FromSeconds(10));
        Assert.Equal(payload, incoming.Data);
        Assert.Equal(1, receiver.Router.CachedResourceProofCount);
        if (localCache) sender.Router.RestoreProofCache(receiver.Router.CaptureProofCache());
        lock (initiator.Gate)
        {
            if (cancel) outgoing.Cancel();
            outgoing.Tick(initiator.Now + Resource.SenderGraceTime + ((outgoing.Rtt ?? initiator.Rtt ?? 1) * Resource.ProofTimeoutFactor) + 1);
        }
        if (cancel)
        {
            Assert.Equal(ResourceStatus.Failed, (await complete.Task.WaitAsync(TimeSpan.FromSeconds(5))).Status);
            Assert.DoesNotContain(left.Sent, packet => packet.Context == LinkContext.CacheRequest);
            return;
        }
        Assert.Equal(ResourceStatus.Complete, (await complete.Task.WaitAsync(TimeSpan.FromSeconds(10))).Status);
        Assert.Equal(ResourceStatus.Complete, outgoing.Status);
        Assert.Equal(!localCache, left.Sent.Any(packet => packet.Context == LinkContext.CacheRequest));
        Assert.Equal(localCache ? 1 : 2, proofs);
    }

    [Fact]
    public async Task CacheReplayIsBoundToTheEstablishedLinksBearer()
    {
        await using var node = await Harness.Create();
        var link = FixedInitiator(node);
        var reference = Vectors.GetProperty("resource");
        node.Router.CacheResourceProof(Packet.Parse(Hex(reference, "proofRaw")));
        var query = Packet.Parse(Hex(reference, "queryRaw"));
        var other = new Probe();
        Assert.False(await node.Router.HandleResourceCacheRequestAsync(Received(query, other), CancellationToken.None));
        Assert.Equal(LinkStatus.Active, link.Status);
    }
}
